// Golden-vector contract: the TS port of opod.schedule must match the vectors the C++ hub port is tested against
// (generated by `python -m opod.golden`). Three ports, one spec.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { setpoint, wakeOffset, validate, type Schedule, type Point } from "../src/lib/schedule.ts";
import { hubYaml } from "../src/lib/hub-yaml.ts";
import model from "../src/data/model.json" with { type: "json" };

const GOLDEN = new URL("../../hub/esphome/components/opod/test/schedule.txt", import.meta.url);
const lines = readFileSync(GOLDEN, "utf8").split("\n");

test("every S and W golden line matches", () => {
  let points: Point[] = [];
  let sched: Schedule | null = null;
  let s = 0;
  let w = 0;
  const blocks: Schedule[] = [];
  for (const line of lines) {
    const f = line.trim().split(/\s+/);
    if (f[0] === "P") {
      points = [];
      for (let k = 1; k < f.length; k += 2) points.push([Number(f[k]), Number(f[k + 1])]);
    } else if (f[0] === "R") {
      sched = { points, wake_ramp_min: Number(f[1]), wake_target_c: Number(f[2]) };
      blocks.push(sched);
    } else if (f[0] === "S") {
      assert.ok(sched, "S line before a P/R block");
      const got = setpoint(sched, Number(f[1]), f[2] === "-" ? null : Number(f[2]));
      if (f[3] === "off") assert.equal(got, null, line);
      else {
        assert.notEqual(got, null, line);
        assert.ok(Math.abs((got as number) - Number(f[3])) <= 1e-4, `${line}: got ${got}`);
      }
      s++;
    } else if (f[0] === "W") {
      assert.equal(wakeOffset(Number(f[1]), Number(f[2])), Number(f[3]), line);
      w++;
    }
  }
  assert.ok(s > 700, `expected the full vector set, got ${s} S lines`);
  assert.ok(w >= 5);
  assert.equal(blocks.length, 2);
  // The first P/R block is the default program, which model.json also carries.
  assert.deepEqual(blocks[0], model.schedule_default);
});

test("validate mirrors Schedule.__post_init__", () => {
  const L = model.limits;
  assert.equal(validate(model.schedule_default.points as Point[], L), null);
  assert.match(validate([], L) ?? "", /at least one/);
  assert.match(validate([[30, 20], [0, 20]], L) ?? "", /sorted/);
  assert.match(validate([[0, 12.9]], L) ?? "", /outside/);
  assert.match(validate([[0, 43.1]], L) ?? "", /outside/);
});

test("hub YAML matches the example config format", () => {
  const yaml = hubYaml(model.schedule_default as Schedule);
  const hub = readFileSync(new URL("../../hub/esphome/opod-hub.yaml", import.meta.url), "utf8");
  // The default program in the example hub config is exactly what the copy button produces.
  assert.ok(hub.includes(yaml), `hub config does not contain:\n${yaml}`);
});
